using System.Text.Json;
using System.Text.Json.Serialization;

namespace MakerCam.Core.Tests;

/// <summary>
/// Replays the golden fixtures generated by <c>dotnet/tools/oracle/oracle.mjs</c>
/// (which runs the original TypeScript core) and requires the C# port to agree.
/// </summary>
public class OracleParityTests
{
    private const double GeometryTolerance = 1e-9;

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
    };

    [Fact]
    public void MatchesTheTypeScriptOracle()
    {
        var fixturePath = System.IO.Path.Combine(AppContext.BaseDirectory, "Fixtures", "oracle.json");
        Assert.True(File.Exists(fixturePath),
            $"Missing oracle fixture at {fixturePath}. Run: node dotnet/tools/oracle/oracle.mjs");

        var fixture = JsonSerializer.Deserialize<OracleFixture>(
            File.ReadAllText(fixturePath), JsonOptions);
        Assert.NotNull(fixture);
        Assert.NotEmpty(fixture!.Cases);

        // Guard against schema drift silently skipping whole sections.
        Assert.Contains(fixture.Cases, c => c.Expected.Import is not null);
        Assert.Contains(fixture.Cases, c => c.Expected.Toolpath is not null);
        Assert.Contains(fixture.Cases, c => c.Expected.Gcode is not null);
        Assert.Contains(fixture.Cases, c => c.Expected.Project is not null);
        Assert.Contains(fixture.Cases, c => c.Gcode is not null);
        Assert.Contains(fixture.Cases, c => c.Toolpath is not null);

        var failures = new List<string>();
        foreach (var c in fixture.Cases)
        {
            try
            {
                RunCase(c);
            }
            catch (Exception ex)
            {
                // Keep going so one broken case does not hide the others.
                failures.Add($"[{c.Name}] {ex.GetType().Name}: {ex.Message}");
            }
        }

        Assert.True(failures.Count == 0,
            $"{failures.Count} oracle case(s) differ from the TypeScript build:\n" +
            string.Join("\n", failures));
    }

    private static void RunCase(OracleCase c)
    {
        var paths = c.Paths?.Select(ToPath).ToList() ?? new List<Path>();

        if (c.Svg is not null)
        {
            var imported = SvgImporter.ParseSvg(c.Svg, new SvgImportOptions
            {
                PxPerInch = c.PxPerInch ?? 96,
            });
            paths = imported.Paths;
            CompareImport(c.Expected.Import, imported);
        }

        GeneratedToolpath? toolpath = null;
        if (c.Toolpath is { } tp)
        {
            var selected = tp.PathIds is { Count: > 0 } ids
                ? paths.Where(p => p.Id is not null && ids.Contains(p.Id)).ToList()
                : paths;
            toolpath = CamEngine.GenerateToolpath(
                ParseType(tp.Type), tp.Params.ToOperationParams(), selected, tp.Tolerance);
            CompareToolpath(c.Expected.Toolpath, toolpath);
        }

        if (c.Gcode is { } gd)
        {
            var op = new Operation
            {
                Id = "op1",
                Type = c.Toolpath is { } t ? ParseType(t.Type) : OperationType.Profile,
                Name = gd.Name ?? "op 1",
                Params = gd.Params.ToOperationParams(),
                Loops = toolpath?.Loops ?? new List<Loop>(),
                DrillPoints = toolpath?.DrillPoints ?? new List<Vec>(),
                Processed = true,
                Visible = true,
            };
            var actual = GcodeGenerator.Generate(new[] { op }, ParseUnit(gd.Unit), gd.Tolerance);
            AssertTextEqual(c.Expected.Gcode, actual, "G-code");
        }

        if (c.Project is { } pd)
        {
            var op = new OpDefinition
            {
                Id = "op1",
                Type = c.Toolpath is { } t ? ParseType(t.Type) : OperationType.Profile,
                Name = pd.Name ?? "profile 1",
                Params = pd.Params.ToOperationParams(),
                PathIds = paths.Where(p => !string.IsNullOrEmpty(p.Id)).Select(p => p.Id!).ToList(),
            };
            var svg = ProjectIO.SerializeProject(paths, new[] { op }, Unit.Mm);
            AssertTextEqual(c.Expected.Project, svg, "Project SVG");

            if (c.Expected.ProjectParsed is { } parsed)
            {
                var roundTripped = ProjectIO.ParseProject(svg);
                CompareProjectParsed(parsed, roundTripped);
            }
        }
    }

    /* -------------------------------------------------------------- */
    /* Comparison                                                      */
    /* -------------------------------------------------------------- */

    private static void CompareImport(ImportExpected? expected, SvgImportResult actual)
    {
        if (expected is null) return;
        AssertEqual(expected.PathCount, actual.Paths.Count, "import.pathCount");
        AssertClose(expected.WidthMm, actual.WidthMm, "import.widthMm");
        AssertClose(expected.HeightMm, actual.HeightMm, "import.heightMm");
        AssertClose(expected.SourceWidth, actual.SourceWidth, "import.sourceWidth");
        AssertClose(expected.SourceHeight, actual.SourceHeight, "import.sourceHeight");
        AssertEqual(expected.HasViewBox, actual.HasViewBox, "import.hasViewBox");
        AssertEqual(
            string.Join(" | ", expected.Warnings),
            string.Join(" | ", actual.Warnings),
            "import.warnings");

        AssertEqual(expected.Paths.Count, actual.Paths.Count, "import.paths.count");
        for (var i = 0; i < expected.Paths.Count; i++)
        {
            var e = expected.Paths[i];
            var a = actual.Paths[i];
            var label = $"import.paths[{i}]";
            AssertEqual(e.Id, a.Id, $"{label}.id");
            AssertEqual(e.Name, a.Name, $"{label}.name");
            AssertEqual(e.SourceId, a.SourceId, $"{label}.sourceId");
            AssertEqual(e.Closed, a.Closed, $"{label}.closed");
            ComparePoints(e.Points, Geom.FlattenPath(a, 0.02), $"{label}.points");
        }
    }

    private static void CompareToolpath(ToolpathExpected? expected, GeneratedToolpath actual)
    {
        if (expected is null) return;
        AssertEqual(
            string.Join(" | ", expected.Warnings),
            string.Join(" | ", actual.Warnings),
            "toolpath.warnings");

        AssertEqual(expected.Loops.Count, actual.Loops.Count, "toolpath.loops.count");
        for (var i = 0; i < expected.Loops.Count; i++)
        {
            var e = expected.Loops[i];
            var a = actual.Loops[i];
            var label = $"toolpath.loops[{i}]";
            AssertEqual(e.Depth, a.Depth, $"{label}.depth");
            AssertEqual(e.Closed, a.Closed, $"{label}.closed");
            AssertEqual(e.PocketDepth, a.PocketDepth, $"{label}.pocketDepth");
            AssertEqual(e.SourceId, a.SourceId, $"{label}.sourceId");
            ComparePoints(e.Points, a.Points, $"{label}.points");

            AssertEqual(e.Tabs.Count, a.Tabs.Count, $"{label}.tabs.count");
            for (var j = 0; j < e.Tabs.Count; j++)
            {
                var tab = e.Tabs[j];
                AssertClose(tab[0], a.Tabs[j].Start, $"{label}.tabs[{j}].start");
                AssertClose(tab[1], a.Tabs[j].Width, $"{label}.tabs[{j}].width");
                AssertClose(tab[2], a.Tabs[j].Height, $"{label}.tabs[{j}].height");
            }
        }

        AssertEqual(expected.DrillPoints.Count, actual.DrillPoints.Count, "toolpath.drillPoints.count");
        ComparePoints(expected.DrillPoints, actual.DrillPoints, "toolpath.drillPoints");
    }

    private static void CompareProjectParsed(ProjectParsedExpected? expected, ProjectData? actual)
    {
        if (expected is null) return;
        Assert.NotNull(actual);
        AssertEqual(expected.PathCount, actual!.Paths.Count, "projectParsed.pathCount");
        AssertEqual(expected.Operations.Count, actual.Operations.Count, "projectParsed.operations.count");

        for (var i = 0; i < expected.Operations.Count; i++)
        {
            var e = expected.Operations[i];
            var a = actual.Operations[i];
            var label = $"projectParsed.operations[{i}]";
            AssertEqual(e.Id, a.Id, $"{label}.id");
            AssertEqual(e.Type, Units.ToCode(a.Type), $"{label}.type");
            AssertEqual(e.Name, a.Name, $"{label}.name");
            AssertEqual(string.Join(",", e.PathIds), string.Join(",", a.PathIds), $"{label}.pathIds");

            AssertClose(e.Params.ToolDiameter, a.Params.ToolDiameter, $"{label}.params.toolDiameter");
            AssertClose(e.Params.TargetDepth, a.Params.TargetDepth, $"{label}.params.targetDepth");
            AssertClose(e.Params.SafetyHeight, a.Params.SafetyHeight, $"{label}.params.safetyHeight");
            AssertClose(e.Params.StockSurface, a.Params.StockSurface, $"{label}.params.stockSurface");
            AssertClose(e.Params.Stepdown, a.Params.Stepdown, $"{label}.params.stepdown");
            AssertClose(e.Params.Feedrate, a.Params.Feedrate, $"{label}.params.feedrate");
            AssertClose(e.Params.Plungerate, a.Params.PlungeRate, $"{label}.params.plungerate");
            AssertEqual(e.Params.Outside, a.Params.Outside, $"{label}.params.outside");
            AssertEqual(e.Params.DirectionValue, (int)a.Params.Direction, $"{label}.params.direction");
            AssertClose(e.Params.Stepover, a.Params.Stepover, $"{label}.params.stepover");
            AssertClose(e.Params.RoughingClearance, a.Params.RoughingClearance, $"{label}.params.roughingClearance");
            AssertEqual(e.Params.Center, a.Params.Center, $"{label}.params.center");
            AssertClose(e.Params.Spacing, a.Params.Spacing, $"{label}.params.spacing");
            AssertEqual(e.Params.HoleCount, a.Params.HoleCount, $"{label}.params.holeCount");
            AssertClose(e.Params.TabSpacing, a.Params.TabSpacing, $"{label}.params.tabSpacing");
            AssertClose(e.Params.TabWidth, a.Params.TabWidth, $"{label}.params.tabWidth");
            AssertClose(e.Params.TabHeight, a.Params.TabHeight, $"{label}.params.tabHeight");
        }
    }

    private static void ComparePoints(List<double[]> expected, IReadOnlyList<Vec> actual, string label)
    {
        AssertEqual(expected.Count, actual.Count, $"{label}.count");
        for (var i = 0; i < expected.Count; i++)
        {
            AssertClose(expected[i][0], actual[i].X, $"{label}[{i}].x");
            AssertClose(expected[i][1], actual[i].Y, $"{label}[{i}].y");
        }
    }

    private static void AssertClose(double expected, double actual, string label)
    {
        if (double.IsNaN(expected) && double.IsNaN(actual)) return;
        if (Math.Abs(expected - actual) <= GeometryTolerance) return;
        throw new Xunit.Sdk.XunitException($"{label}: expected {expected:R}, got {actual:R}");
    }

    private static void AssertEqual<T>(T expected, T actual, string label)
    {
        if (EqualityComparer<T>.Default.Equals(expected, actual)) return;
        throw new Xunit.Sdk.XunitException($"{label}: expected {expected}, got {actual}");
    }

    private static void AssertTextEqual(string? expected, string actual, string label)
    {
        if (expected is null) return;
        if (string.Equals(expected, actual, StringComparison.Ordinal)) return;

        var e = expected.Split('\n');
        var a = actual.Split('\n');
        var line = 0;
        while (line < Math.Min(e.Length, a.Length) && e[line] == a[line]) line++;

        throw new Xunit.Sdk.XunitException(
            $"{label} differs at line {line + 1}:\n" +
            $"  expected: {e.ElementAtOrDefault(line)?.TrimEnd('\r')}\n" +
            $"  actual:   {a.ElementAtOrDefault(line)?.TrimEnd('\r')}\n" +
            $"  (expected {e.Length} lines, got {a.Length})");
    }

    /* -------------------------------------------------------------- */
    /* Fixture conversion                                              */
    /* -------------------------------------------------------------- */

    private static Path ToPath(PathDto dto) => new()
    {
        Id = dto.Id,
        Name = dto.Name,
        SourceId = dto.SourceId,
        Closed = dto.Closed,
        Segments = dto.Segments.Select(ToSegment).ToList(),
    };

    private static Segment ToSegment(SegmentDto dto) => dto.Kind switch
    {
        "line" => new LineSegment(V(dto.P1!), V(dto.P2!)),
        "quad" => new QuadSegment(V(dto.P1!), V(dto.C!), V(dto.P2!)),
        "cubic" => new CubicSegment(V(dto.P1!), V(dto.C1!), V(dto.C2!), V(dto.P2!)),
        _ => throw new Xunit.Sdk.XunitException($"Unknown segment kind '{dto.Kind}'"),
    };

    private static Vec V(VecDto v) => new(v.X, v.Y);

    private static OperationType ParseType(string type) => Units.ParseOperationType(type);

    private static Unit ParseUnit(string unit) => Units.ParseUnit(unit);

    /* -------------------------------------------------------------- */
    /* Fixture models                                                  */
    /* -------------------------------------------------------------- */

    public sealed class OracleFixture
    {
        public int Version { get; set; }
        public List<OracleCase> Cases { get; set; } = new();
    }

    public sealed class OracleCase
    {
        public string Name { get; set; } = string.Empty;
        public string? Svg { get; set; }
        public double? PxPerInch { get; set; }
        public List<PathDto>? Paths { get; set; }
        public ToolpathDto? Toolpath { get; set; }
        public GcodeDto? Gcode { get; set; }
        public ProjectDto? Project { get; set; }
        public ExpectedDto Expected { get; set; } = new();
    }

    public sealed class VecDto
    {
        public double X { get; set; }
        public double Y { get; set; }
    }

    public sealed class SegmentDto
    {
        public string Kind { get; set; } = string.Empty;
        public VecDto? P1 { get; set; }
        public VecDto? P2 { get; set; }
        public VecDto? C { get; set; }
        public VecDto? C1 { get; set; }
        public VecDto? C2 { get; set; }
    }

    public sealed class PathDto
    {
        public string? Id { get; set; }
        public string? Name { get; set; }
        public string? SourceId { get; set; }
        public bool Closed { get; set; }
        public List<SegmentDto> Segments { get; set; } = new();
    }

    public sealed class ParamsDto
    {
        public double ToolDiameter { get; set; }
        public double TargetDepth { get; set; }
        public double SafetyHeight { get; set; }
        public double StockSurface { get; set; }
        public double Stepdown { get; set; }
        public double Feedrate { get; set; }
        public double Plungerate { get; set; }
        public bool Outside { get; set; }

        [JsonPropertyName("direction")]
        public int DirectionValue { get; set; }

        public double Stepover { get; set; }
        public double RoughingClearance { get; set; }
        public bool Center { get; set; }
        public double Spacing { get; set; }
        public int HoleCount { get; set; }
        public double TabSpacing { get; set; }
        public double TabWidth { get; set; }
        public double TabHeight { get; set; }

        public OperationParams ToOperationParams() => new()
        {
            ToolDiameter = ToolDiameter,
            TargetDepth = TargetDepth,
            SafetyHeight = SafetyHeight,
            StockSurface = StockSurface,
            Stepdown = Stepdown,
            Feedrate = Feedrate,
            PlungeRate = Plungerate,
            Outside = Outside,
            Direction = DirectionValue == 2 ? MakerCam.Core.Direction.Clockwise : MakerCam.Core.Direction.CounterClockwise,
            Stepover = Stepover,
            RoughingClearance = RoughingClearance,
            Center = Center,
            Spacing = Spacing,
            HoleCount = HoleCount,
            TabSpacing = TabSpacing,
            TabWidth = TabWidth,
            TabHeight = TabHeight,
        };
    }

    public sealed class ToolpathDto
    {
        public string Type { get; set; } = "profile";
        public ParamsDto Params { get; set; } = new();
        public List<string>? PathIds { get; set; }
        public double Tolerance { get; set; } = 0.02;
    }

    public sealed class GcodeDto
    {
        public string Unit { get; set; } = "mm";
        public double Tolerance { get; set; } = 0.01;
        public ParamsDto Params { get; set; } = new();
        public string? Name { get; set; }
    }

    public sealed class ProjectDto
    {
        public string? Name { get; set; }
        public ParamsDto Params { get; set; } = new();
    }

    public sealed class ExpectedDto
    {
        public ImportExpected? Import { get; set; }
        public ToolpathExpected? Toolpath { get; set; }
        public string? Gcode { get; set; }
        public string? Project { get; set; }
        public ProjectParsedExpected? ProjectParsed { get; set; }
    }

    public sealed class ImportExpected
    {
        public int PathCount { get; set; }
        public double WidthMm { get; set; }
        public double HeightMm { get; set; }
        public double SourceWidth { get; set; }
        public double SourceHeight { get; set; }
        public bool HasViewBox { get; set; }
        public List<string> Warnings { get; set; } = new();
        public List<PathExpected> Paths { get; set; } = new();
    }

    public sealed class PathExpected
    {
        public string? Id { get; set; }
        public string? Name { get; set; }
        public string? SourceId { get; set; }
        public bool Closed { get; set; }
        public List<double[]> Points { get; set; } = new();
    }

    public sealed class ToolpathExpected
    {
        public List<LoopExpected> Loops { get; set; } = new();
        public List<double[]> DrillPoints { get; set; } = new();
        public List<string> Warnings { get; set; } = new();
    }

    public sealed class LoopExpected
    {
        public List<double[]> Points { get; set; } = new();
        public int Depth { get; set; }
        public bool Closed { get; set; }
        public int PocketDepth { get; set; }
        public List<double[]> Tabs { get; set; } = new();
        public string? SourceId { get; set; }
    }

    public sealed class ProjectParsedExpected
    {
        public int PathCount { get; set; }
        public List<OpExpected> Operations { get; set; } = new();
        public List<string> Warnings { get; set; } = new();
    }

    public sealed class OpExpected
    {
        public string? Id { get; set; }
        public string Type { get; set; } = "profile";
        public string Name { get; set; } = string.Empty;
        public ParamsDto Params { get; set; } = new();
        public List<string> PathIds { get; set; } = new();
    }
}
